"""An explicitly fictional restaurant example; never a substitute for generation."""
from html import escape


def restaurant_starter(name, assets=()):
    brand = escape(name or 'LASTRO', quote=True)
    photo = ('<img src="assets/' + escape(assets[0], quote=True) + '" alt="Fotografia ilustrativa gerada por IA: peixe na brasa em uma cozinha fictícia" width="1536" height="1024">') if assets else '<div class="photo-placeholder"><span>01 / A COZINHA EM IMAGEM</span><p>Uma fotografia da casa<br>faz parte da história.</p></div>'
    html = f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{brand} — cozinha de mar e fogo</title><meta name="description" content="Projeto fictício de cozinha brasileira no fogo. Cardápio ilustrativo e solicitação de mesa para demonstração."><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head>
<body><a class="skip" href="#principal">Ir para o conteúdo</a>
<div class="demo-note">ESTUDO DE DESIGN · RESTAURANTE FICTÍCIO · FOTOGRAFIA ILUSTRATIVA GERADA POR IA</div>
<header class="masthead"><a class="wordmark" href="#principal">{brand}</a><div class="masthead-side"><span>COZINHA DE MAR E FOGO</span><nav aria-label="Navegação principal"><a href="#cozinha">A cozinha</a><a href="#cardapio">O que vai à mesa</a><a class="reserve" href="#mesa">Pedir uma mesa <span aria-hidden="true">↗</span></a></nav></div></header>
<main id="principal"><section class="opening" aria-labelledby="headline"><div class="opening-note"><span class="eyebrow">01 / O QUE NOS MOVE</span><h1 id="headline">O mar decide.<br><em>A brasa transforma.</em></h1><p>Peixe inteiro, farofa bem feita e tempo para ficar à mesa. Nossa cozinha começa pelo ingrediente.</p><a class="text-link" href="#cardapio">Conheça o cardápio <span aria-hidden="true">↗</span></a></div><figure class="opening-photo">{photo}<figcaption>Uma cozinha imaginada pelo Cronos Studio. Imagem ilustrativa.</figcaption><span class="photo-seal">MAR<br>E FOGO</span></figure><aside class="daily-menu"><span class="eyebrow">02 / UM GOSTO DA CASA</span><h2>Hoje,<br>na brasa.</h2><a href="#cardapio"><span>01</span><h3>Peixe do dia</h3><p>Pirão, farofa de dendê e limão tostado.</p></a><a href="#cardapio"><span>02</span><h3>Abóbora assada</h3><p>Manteiga de garrafa, castanha e ervas.</p></a><a href="#cardapio"><span>03</span><h3>Cocada de forno</h3><p>Quente na colher, com sorvete de coco.</p></a><span class="small-note">Pratos e valores deste estudo são ilustrativos.</span></aside></section>
<section id="cozinha" class="kitchen"><div><span class="eyebrow">03 / SEM PRESSA DE SAIR</span><h2>A mesa é parte<br>da cozinha.</h2></div><div class="kitchen-copy"><p>Do fogo vem a casquinha. Da panela, o caldo. No meio da mesa, um prato para dividir e uma conversa que pode continuar.</p><p>Esta proposta demonstra uma identidade de restaurante. Ao personalizar, entram a história, as fotografias e os ingredientes reais de cada casa.</p><a class="text-link" href="#mesa">Vamos marcar uma mesa? <span aria-hidden="true">↗</span></a></div></section>
<section id="cardapio" class="menu-section"><div class="section-heading"><div><span class="eyebrow">04 / CARDÁPIO ILUSTRATIVO</span><h2>O que vai<br>à mesa.</h2></div><p>Uma pequena seleção para experimentar a navegação. Ingredientes, preços e disponibilidade precisam ser confirmados para um negócio real.</p></div><div class="menu-filters" role="group" aria-label="Filtrar cardápio"><button type="button" data-filter="all" aria-pressed="true">Tudo</button><button type="button" data-filter="entrada" aria-pressed="false">Para começar</button><button type="button" data-filter="principal" aria-pressed="false">Da brasa</button><button type="button" data-filter="doce" aria-pressed="false">Para terminar</button><button type="button" data-filter="bebida" aria-pressed="false">No copo</button></div><div class="menu-items">
<article data-type="entrada"><span class="dish-number">01</span><div><h3>Bolinho de peixe</h3><p>Casquinha fina, pimenta da casa e limão.</p></div><span class="price">R$ 32</span><button type="button" data-dish="Bolinho de peixe" data-description="Porção ilustrativa de seis bolinhos de peixe com molho de pimenta e limão. Contém peixe e trigo. Confirme composição e alergênicos com o restaurante real.">Detalhes <span aria-hidden="true">↗</span></button></article>
<article data-type="principal"><span class="dish-number">02</span><div><h3>Peixe do dia na brasa</h3><p>Inteiro, com pirão e farofa de dendê. Para dividir.</p></div><span class="price">R$ 148</span><button type="button" data-dish="Peixe do dia na brasa" data-description="Prato ilustrativo para duas pessoas. O peixe e seus acompanhamentos dependem da disponibilidade de cada casa. Contém peixe; confirme os demais alergênicos antes do pedido.">Detalhes <span aria-hidden="true">↗</span></button></article>
<article data-type="principal"><span class="dish-number">03</span><div><h3>Abóbora, castanha e fogo</h3><p>Assada devagar, com ervas e manteiga de garrafa.</p></div><span class="price">R$ 54</span><button type="button" data-dish="Abóbora, castanha e fogo" data-description="Prato vegetariano ilustrativo com abóbora assada, castanhas e manteiga de garrafa. Contém leite e castanhas. Não é uma opção vegana nesta composição.">Detalhes <span aria-hidden="true">↗</span></button></article>
<article data-type="doce"><span class="dish-number">04</span><div><h3>Cocada de forno</h3><p>Coco tostado, calda morna e sorvete de coco.</p></div><span class="price">R$ 26</span><button type="button" data-dish="Cocada de forno" data-description="Sobremesa ilustrativa servida quente com sorvete. Pode conter leite e ovos. Valores e composição devem ser confirmados na personalização.">Detalhes <span aria-hidden="true">↗</span></button></article>
<article data-type="bebida"><span class="dish-number">05</span><div><h3>Caju e limão</h3><p>Refresco da casa, sem álcool, feito na hora.</p></div><span class="price">R$ 18</span><button type="button" data-dish="Caju e limão" data-description="Bebida ilustrativa sem álcool. Suco de caju, limão e gelo. Ajuste ingredientes e informações alimentares com o responsável antes de publicar.">Detalhes <span aria-hidden="true">↗</span></button></article>
</div><p class="menu-count" role="status">5 opções no cardápio ilustrativo.</p></section>
<section id="mesa" class="table-section"><div><span class="eyebrow">05 / FIQUE PARA A CONVERSA</span><h2>Um lugar<br>à sua mesa.</h2><p>Escolha uma data e envie uma solicitação. O envio não confirma a reserva: depende do retorno e da disponibilidade da equipe.</p><details><summary>Endereço e horários</summary><p>Dados pendentes de personalização. Este restaurante é fictício; não há endereço ou horário comercial real cadastrado.</p></details></div><form data-studio-form="booking"><label>Seu nome<input name="name" autocomplete="name" maxlength="100" required></label><label>E-mail para retorno<input name="email" type="email" autocomplete="email" maxlength="180" required></label><div class="form-row"><label>Data<input name="date" type="date" required></label><label>Horário<input name="time" type="time" required></label></div><label>Quantidade de pessoas<select name="service" required><option value="Mesa para 2 pessoas">2 pessoas</option><option value="Mesa para 4 pessoas">4 pessoas</option><option value="Mesa para 6 pessoas">6 pessoas</option><option value="Mesa para 8 ou mais pessoas">8 ou mais — consultar a equipe</option></select></label><label class="consent"><input name="consent" type="checkbox" required>Autorizo o uso dos dados para responder a esta solicitação.</label><button class="solid-button" type="submit">Solicitar mesa <span aria-hidden="true">↗</span></button><p data-form-status role="status"></p></form></section>
<section id="contato" class="contact-section"><div><span class="eyebrow">06 / ANTES DE VIR</span><h2>Tem alguma<br>pergunta?</h2><p>Converse sobre o cardápio, acessibilidade ou uma ocasião especial. Na demonstração, o envio é registrado localmente; não há e-mail automático para um restaurante.</p></div><form data-studio-form="contact"><label>Nome<input name="name" autocomplete="name" maxlength="100" required></label><label>E-mail<input name="email" type="email" autocomplete="email" maxlength="180" required></label><label>Telefone (opcional)<input name="phone" type="tel" autocomplete="tel" maxlength="32"></label><label>O que gostaria de saber?<textarea name="message" maxlength="3000" required></textarea></label><label class="consent"><input name="consent" type="checkbox" required>Concordo com o uso dos dados para receber uma resposta.</label><button class="solid-button" type="submit">Enviar mensagem <span aria-hidden="true">↗</span></button><p data-form-status role="status"></p></form></section></main>
<footer><a class="footer-brand" href="#principal">{brand}</a><p>Restaurante fictício · estudo de design do Cronos Studio.<br>Imagem ilustrativa gerada por IA. Conteúdo e valores de demonstração.</p><a href="#mesa">Pedir uma mesa ↗</a></footer>
<dialog id="dish-dialog" aria-labelledby="dish-title"><button class="dialog-close" type="button" aria-label="Fechar detalhes do prato">×</button><span class="eyebrow">DO CARDÁPIO / DEMONSTRAÇÃO</span><h2 id="dish-title"></h2><p id="dish-description"></p><a class="solid-button" href="#mesa">Consultar uma mesa ↗</a></dialog>
</body></html>'''
    css = '''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;background:#f2ede2;color:#261c17;font-family:Arial,sans-serif}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button,a{touch-action:manipulation}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #ba351e;outline-offset:5px}button{cursor:pointer}button:disabled{opacity:.5}.skip{position:absolute;top:-100px;left:12px;background:#fff;padding:15px;z-index:10}.skip:focus{top:8px}.demo-note{background:#2b211b;color:#e4d9c9;text-align:center;font:9px/1.5 Arial,sans-serif;letter-spacing:.15em;padding:9px 20px}.masthead{display:flex;align-items:end;justify-content:space-between;gap:35px;padding:14px 3vw 20px;border-bottom:1px solid #a99a85}.wordmark{font:500 clamp(60px,11vw,164px)/.8 Georgia,serif;letter-spacing:-.075em;color:#71331f;max-width:65%;overflow-wrap:anywhere}.masthead-side{display:flex;flex-direction:column;gap:20px;align-items:end;padding-bottom:5px}.masthead-side>span{font:9px Arial,sans-serif;letter-spacing:.22em}nav{display:flex;align-items:center;gap:30px;font-size:12px}nav>a:not(.reserve){border-bottom:1px solid #887665;padding:8px 0}.reserve{background:#ba351e;color:#fff6e9;padding:14px 18px;border-radius:40px}.reserve span{margin-left:12px}.opening{display:grid;grid-template-columns:23% 56% 21%;min-height:540px}.eyebrow{display:block;font:9px/1.7 Arial,sans-serif;letter-spacing:.18em}.opening-note{padding:34px 2.5vw}.opening h1{font:400 clamp(34px,4.2vw,66px)/.96 Georgia,serif;letter-spacing:-.06em;margin:35px 0 25px}.opening em{font-style:normal;color:#b3331e}.opening-note>p{font:15px/1.7 Georgia,serif;max-width:255px}.text-link{display:inline-block;font-size:11px;border-bottom:1px solid;padding:10px 0;margin-top:20px}.text-link span{margin-left:20px}.opening-photo{margin:0;position:relative;min-width:0;overflow:hidden;background:#291c14}.opening-photo img{display:block;position:absolute;width:100%;height:100%;object-fit:cover;object-position:58% center}.opening-photo figcaption{position:absolute;bottom:0;left:0;right:0;padding:35px 18px 15px;background:linear-gradient(transparent,#000a);color:#f6e8d8;font:9px/1.5 Arial,sans-serif}.photo-seal{position:absolute;top:25px;right:20px;border:2px solid #f28457;color:#ffb18a;border-radius:50%;padding:20px 12px;font:11px/1.5 Arial,sans-serif;letter-spacing:.18em;transform:rotate(12deg);text-align:center}.daily-menu{padding:34px 2vw 20px}.daily-menu h2{font:400 39px/.95 Georgia,serif;letter-spacing:-.04em;margin:27px 0}.daily-menu>a{display:block;border-top:1px solid #bbad9a;padding:18px 0 15px}.daily-menu>a>span{font-size:8px;color:#8c6754}.daily-menu h3{font:400 22px/1.1 Georgia,serif;margin:10px 0 7px;letter-spacing:-.02em}.daily-menu p{font:12px/1.6 Georgia,serif;margin:0}.small-note{font:9px/1.6 Arial,sans-serif;color:#765f50;display:block;margin-top:8px}.photo-placeholder{padding:60px 30px;color:#f5dcc3;height:100%;background:linear-gradient(145deg,#442e1f,#1a1710)}.photo-placeholder span{font-size:9px;letter-spacing:.2em}.photo-placeholder p{font:35px/1.1 Georgia,serif}.kitchen{background:#cc4024;display:grid;grid-template-columns:1.35fr 1fr;gap:10vw;padding:55px 5vw 65px}.kitchen h2{font:400 clamp(46px,6.8vw,100px)/.95 Georgia,serif;letter-spacing:-.055em;margin:25px 0 0}.kitchen-copy{padding-top:25px;max-width:450px}.kitchen-copy p{font:17px/1.7 Georgia,serif}.kitchen-copy p+p{font:12px/1.8 Arial,sans-serif;max-width:370px}.menu-section{padding:80px 7vw}.section-heading{display:flex;align-items:end;justify-content:space-between;gap:40px}.section-heading h2,.table-section h2,.contact-section h2{font:400 clamp(42px,5.5vw,78px)/.95 Georgia,serif;letter-spacing:-.05em;margin:23px 0 30px}.section-heading>p{max-width:350px;font-size:12px;line-height:1.9;margin:0 0 32px}.menu-filters{display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid #aa9782;padding-bottom:22px}.menu-filters button{background:none;border:1px solid #beaf9b;border-radius:30px;padding:10px 17px;font-size:11px;color:#261c17}.menu-filters button[aria-pressed=true]{background:#291e17;border-color:#291e17;color:#f3e7d5}.menu-items article{display:grid;grid-template-columns:40px 1fr 90px 85px;align-items:center;gap:20px;padding:25px 0;border-bottom:1px solid #c8bca9}.menu-items article[hidden]{display:none}.dish-number{font-size:9px;color:#94735b}.menu-items h3{font:400 28px/1.1 Georgia,serif;letter-spacing:-.03em;margin:0 0 10px}.menu-items p{font:12px/1.6 Arial,sans-serif;color:#755f4e;margin:0}.price{font:18px Georgia,serif;text-align:right}.menu-items button{background:none;border:0;border-bottom:1px solid;color:#733f2d;font-size:10px;padding:10px 0}.menu-count{font-size:10px;color:#725e4c;margin-top:20px}.table-section,.contact-section{display:grid;grid-template-columns:1fr 1fr;gap:12vw;padding:70px 8vw;border-top:1px solid #ae9c83}.table-section{background:#2c3125;color:#f2ecdb}.table-section>div>p,.contact-section>div>p{max-width:360px;font-size:13px;line-height:1.9}.table-section details{font-size:12px;margin-top:30px}.table-section summary{cursor:pointer}.table-section details p{max-width:350px;line-height:1.8;color:#c6c7ae}form{display:grid;gap:18px}form label{display:flex;flex-direction:column;gap:8px;font-size:11px}input,select,textarea{width:100%;min-width:0;border:0;border-bottom:1px solid #a89e8a;background:transparent;color:inherit;padding:11px 0;border-radius:0}select option{background:#f3ecdd;color:#261c17}textarea{min-height:80px;resize:vertical}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:25px}.consent{flex-direction:row;align-items:center;line-height:1.7}.consent input{width:16px;min-width:16px;accent-color:#bd4025}.solid-button{display:inline-flex;align-items:center;justify-content:space-between;gap:25px;border:0;background:#bc3b22;color:#fff4e2;padding:17px 22px;font-size:11px;min-height:48px;text-align:left}.table-section .solid-button{background:#e9dfc9;color:#292d21}[data-form-status]{font-size:12px;line-height:1.8;min-height:1em;margin:0}footer{display:flex;justify-content:space-between;align-items:center;gap:30px;border-top:1px solid #b8a58b;padding:35px 5vw}.footer-brand{font:40px Georgia,serif;letter-spacing:-.06em}footer p{font-size:9px;line-height:1.8;color:#735b47}footer>a:last-child{font-size:11px;border-bottom:1px solid;padding:7px 0}dialog{max-width:min(520px,calc(100vw - 30px));border:0;background:#f3ecdf;color:#2a2018;padding:45px}dialog::backdrop{background:#130d09b5;backdrop-filter:blur(3px)}dialog h2{font:38px/1 Georgia,serif;letter-spacing:-.04em}dialog p{font:14px/1.9 Arial,sans-serif}.dialog-close{position:absolute;top:12px;right:15px;border:0;background:none;font-size:27px;color:#261c17}dialog .solid-button{margin-top:20px}@media(max-width:950px){.masthead{align-items:center}.masthead-side>span{display:none}nav{gap:15px}nav>a:not(.reserve){display:none}.opening{grid-template-columns:35% 65%}.opening h1{font-size:48px}.daily-menu{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;padding:25px}.daily-menu>.eyebrow,.daily-menu>h2,.daily-menu>.small-note{grid-column:1/-1}.daily-menu>h2{margin:0;font-size:34px}.daily-menu>a{padding:15px 0}.kitchen{gap:5vw}.menu-section{padding:55px 5vw}}@media(max-width:600px){.demo-note{font-size:7px;padding:8px 13px;letter-spacing:.09em}.masthead{padding:22px 18px}.wordmark{font-size:63px;max-width:62%}.reserve{font-size:9px;padding:12px}.reserve span{margin-left:5px}.opening{display:flex;flex-direction:column}.opening-note{padding:28px 23px 35px}.opening h1{font-size:59px;max-width:340px;margin:25px 0 20px}.opening-note>p{font-size:16px;max-width:300px}.opening-photo{min-height:380px}.opening-photo img{object-position:60% center}.daily-menu{padding:32px 23px;gap:15px;grid-template-columns:1fr}.daily-menu h3{font-size:28px}.daily-menu>h2{font-size:40px}.daily-menu p{font-size:14px}.kitchen{grid-template-columns:1fr;padding:40px 23px;gap:0}.kitchen h2{font-size:62px}.kitchen-copy p{font-size:18px}.kitchen-copy p+p{font-size:13px}.menu-section{padding:48px 23px}.section-heading{display:block}.section-heading h2{font-size:56px}.section-heading>p{font-size:13px}.menu-filters{gap:7px}.menu-filters button{font-size:10px;padding:10px 12px}.menu-items article{grid-template-columns:20px 1fr 65px;gap:12px}.menu-items h3{font-size:25px}.menu-items p{font-size:12px}.menu-items button{grid-column:2/4;justify-self:start;min-width:100px}.price{font-size:16px}.table-section,.contact-section{grid-template-columns:1fr;gap:25px;padding:45px 23px}.table-section h2,.contact-section h2{font-size:60px}.table-section>div>p,.contact-section>div>p{font-size:14px}form label{font-size:12px}.form-row{gap:15px}footer{flex-wrap:wrap;padding:30px 23px;gap:20px}footer p{order:3;font-size:10px}.footer-brand{font-size:34px}dialog{padding:40px 25px}dialog h2{font-size:32px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}'''
    js = '''const filters=document.querySelectorAll('[data-filter]');const dishes=document.querySelectorAll('[data-type]');const count=document.querySelector('.menu-count');filters.forEach(button=>button.addEventListener('click',()=>{let visible=0;filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));dishes.forEach(dish=>{dish.hidden=button.dataset.filter!=='all'&&dish.dataset.type!==button.dataset.filter;if(!dish.hidden)visible++;});count.textContent=visible+(visible===1?' opção nesta seleção.':' opções nesta seleção.');}));const dialog=document.querySelector('#dish-dialog');let trigger=null;document.querySelectorAll('[data-dish]').forEach(button=>button.addEventListener('click',()=>{trigger=button;document.querySelector('#dish-title').textContent=button.dataset.dish;document.querySelector('#dish-description').textContent=button.dataset.description;dialog.showModal();}));const closeDish=()=>{dialog.close();if(trigger)trigger.focus();};document.querySelector('.dialog-close').addEventListener('click',closeDish);dialog.querySelector('a').addEventListener('click',closeDish);dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)closeDish();}});document.querySelectorAll('input[type="date"]').forEach(input=>{const d=new Date();input.min=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');});'''
    return {'index.html': html, 'styles.css': css, 'app.js': js}
